<!--
  代码编辑器 (Monaco 宿主)。

  ⚠️ **建实例的 effect 只应依赖"实例标识" (`doc.path`), 体内其余读取必须 `untrack()`**:
  `$effect` 会把体内所有同步读取都变成依赖, 漏掉就会因"每次按键都改 `doc.content`"而反复
  销毁重建 Monaco 编辑器, 光标、滚动位置、撤销栈全部丢失。effect 因此严格分成两类, 绝不混用:

    1. **建实例** (见下 §1): 只依赖显式的"实例标识" (`doc.path`), 体内其余读取一律 `untrack()`;
    2. **更新实例** (见下 §2): 只把某个值推给已存在的编辑器, 不创建也不销毁。

  Monaco 的 model 由 `lsp/monaco.ts` 的 `openModel` 按路径复用, 因此**撤销栈按文档存活**,
  切卡只重建编辑器实例。
-->

<script lang="ts">
  import { openUrl } from '@tauri-apps/plugin-opener';
  import * as monaco from 'monaco-editor';
  import { untrack } from 'svelte';

  import { gitFileChanges, gitFileRegion } from '../commands/git';
  import { pathDrag, registerPathDropTarget } from '../dnd/path-drag.svelte';
  import { createDocumentSaver } from '../editor/document-saver';
  import { diffGutterMarks } from '../editor/diff-gutter';
  import { createLivePreviewGutterController } from '../editor/gutter-live-preview';
  import { createInlineDiffZoneController } from '../editor/inline-diff-zone';
  import { fs } from '../lib/fs';
  import { lspClient } from '../lsp/client';
  import { applyDiagnostics, bindModel, LANGUAGE_ID, openModel, TRIGGER_CHARACTERS } from '../lsp/monaco';
  import { previewClient } from '../preview/client';
  import type { OpenDocument } from '../state/store.svelte';
  import { actions, appStore } from '../state/store.svelte';
  import { watchValues } from '../state/watch.svelte';

  let {
    doc,
    /** 只读 (配音卡) */
    readOnly = false,
    /** 需要整行高亮的行 (0 基, 与后端一致); 配音卡用它指出当前语句 */
    highlightLine = null,
  }: {
    doc: OpenDocument;
    readOnly?: boolean;
    highlightLine?: { line: number; count: number } | null;
  } = $props();

  let host: HTMLDivElement | undefined = $state();
  let editor: monaco.editor.IStandaloneCodeEditor | null = null;

  const TRIGGER_SET = new Set<string>(TRIGGER_CHARACTERS);
  const AUTOSAVE_DELAY = 800;
  const PREVIEW_SYNC_DELAY = 400;

  /** 外部回灌内容时置位, 避免把这次变更当成"用户编辑"写回 store (会标脏)。 */
  let pushingExternal = false;

  /**
   * 当前实例的"防抖同步预览"入口。
   *
   * 由**建实例**的 effect 填充, 供**外部内容回灌**那个 effect 使用: 回灌发生在实例之外 (它监听
   * store 的 `doc.content`), 而 `scheduleSync` 需要实例内的 `docSaver`/光标, 因此用一个 ref 把
   * 两者接起来。
   */
  let syncRef: (() => void) | null = null;

  const settings = $derived(appStore.settings);

  /**
   * 编辑器构造选项: 只由设置决定, 因此设置一变整体重算。
   *
   * ⚠️ 有三项**看着像可省的调试开关, 实际是功能开关**, 删掉会静默失效:
   *
   * * `'semanticHighlighting.enabled': true` —— Monaco 内置主题的 semanticHighlighting 恒为
   *   `false`, 不显式打开, 语言服务算出来的语义 token **根本不会被请求**, 整篇脚本只剩语法
   *   着色。客户端侧找不到任何报错, 只是颜色不对。
   * * `glyphMargin: isScene` —— 行号右侧那一栏是**实时预览指示器**画的地方 (与 git 色块并排)。
   *   关掉之后指示器与"点击重跑"一起消失, 而控制器的代码仍然在跑, 没有任何提示。只给场景
   *   文件开: 普通资源文本上多一条空栏纯属挤占。
   * * `domReadOnly: readOnly` —— 只读时不显示光标插入符, 免得用户以为可以编辑。
   */
  const editorOptions = $derived<monaco.editor.IStandaloneEditorConstructionOptions>({
    language: doc.isScene ? LANGUAGE_ID : undefined,
    theme: appStore.theme === 'dark' ? 'webgal-dark' : 'webgal-light',
    readOnly,
    domReadOnly: readOnly,
    glyphMargin: doc.isScene,
    automaticLayout: true,
    minimap: { enabled: settings.editorMinimap },
    fontFamily: settings.editorFontFamily,
    fontSize: settings.editorFontSize,
    wordWrap: settings.editorWordWrap ? 'on' : 'off',
    /*
     * **不要设 `scrollBeyondLastLine`** —— Monaco 的默认值是 `true` (允许滚过最后一行)。
     * 设成 `false` 会让最后一行最多只能滑到底端, 再往上滑不动。
     */
    renderWhitespace: 'none',
    fixedOverflowWidgets: true,
    tabSize: 2,
    // 当前语句整行高亮 (配音卡用它表示"正在配置哪一句")
    renderLineHighlight: 'all',
    'semanticHighlighting.enabled': true,
  });

  /*
   * 每个编辑器实例挂两份装饰集合 (git 色块 / 整行高亮)。
   *
   * 用 `WeakMap` 而不是组件变量: 下面几个"更新实例"的 effect 会各自重建, 而集合必须跟着实例走;
   * 实例销毁后条目由弱引用回收, 不会泄漏。
   */
  const gitCollections = new WeakMap<monaco.editor.IStandaloneCodeEditor, monaco.editor.IEditorDecorationsCollection>();
  const highlightCollections = new WeakMap<
    monaco.editor.IStandaloneCodeEditor,
    monaco.editor.IEditorDecorationsCollection
  >();

  function collectionFor(
    store: typeof gitCollections,
    instance: monaco.editor.IStandaloneCodeEditor
  ): monaco.editor.IEditorDecorationsCollection {
    let collection = store.get(instance);
    if (!collection) {
      collection = instance.createDecorationsCollection();
      store.set(instance, collection);
    }
    return collection;
  }

  /**
   * 项目内相对路径 (git 后端要的是这个, 不是绝对路径)。
   *
   * 两个 effect 都要用, 因此提出来一份 —— 分别实现很容易在其中一个里漏掉大小写或分隔符处理。
   */
  function relativePathOf(projectPath: string, filePath: string): string {
    const base = projectPath.replace(/\\/g, '/').replace(/\/+$/, '');
    const full = filePath.replace(/\\/g, '/');
    return full.toLowerCase().startsWith(`${base.toLowerCase()}/`) ? full.slice(base.length + 1) : full;
  }

  // ---------------------------------------------------------------------------
  // 1. 建实例 —— 只在 doc.path 变化时执行
  // ---------------------------------------------------------------------------

  $effect(() => {
    // 唯一的显式依赖: 是哪个文档。
    const path = doc.path;
    /*
     * `host` 是 `$state` 变量, 在 `untrack` 回调里 TS 保留不了上面那句的收窄 —— 先取出一个
     * 不可变引用再进回调。读取 `host` 本身仍留在外面: 宿主节点被换掉时必须重建编辑器。
     */
    const container = host;
    if (!container) return;

    /*
     * 从这里往下**整块不追踪** —— 这是"只依赖实例标识"这条规矩的落地方式。
     *
     * 必须整块包住, 而不是一个个读取去 `untrack`: 这个 effect 会调用若干"读 store"的函数 ——
     * `applyDiagnostics()` 读 `useAppStore.getState().diagnostics[path]`, 下面还有直接读
     * `appStore.previewReady` 的语句 —— 而 `useAppStore.getState()` **运行期返回的就是 `$state`
     * 代理本身** (见 `state/store.svelte.ts` 的 `getState`), 于是这些读取全成了本 effect 的依赖:
     * 语言服务按项目重推诊断 → `diagnostics[场景路径]` 被换成**新数组** → effect 重跑 →
     * `instance.dispose()` + `monaco.editor.create()` 重建编辑器, 实测每秒 1.5 次 (只有场景文件
     * 会闪, 因为诊断只覆盖场景)。整块包住之后, "顺手多读了一个字段"不会再悄悄把编辑器变成
     * 每秒重建一次 —— 这类回归光靠读代码很难发现, 而它毁掉的是光标/滚动/撤销栈与整块画面。
     */
    return untrack(() => {
      const { isScene, content, options } = untrack(() => ({
        isScene: doc.isScene,
        content: doc.content,
        options: editorOptions,
      }));

      const model = openModel(path, content);
      const instance = monaco.editor.create(container, { ...options, model });
      editor = instance;

      // 恢复该文档上次的光标位置 (切走再切回来不回到第一行)
      const stored = untrack(() => appStore.cursors[path]);
      if (stored) {
        const line = Math.min(stored.line, model.getLineCount());
        instance.setPosition({ lineNumber: line, column: stored.column });
        instance.revealLineInCenterIfOutsideViewport(line);
      }

      /*
       * **实例刚建好就补做一次待处理的跳转请求。**
       *
       * 点诊断的路径是"先写请求、再读文件" (`Diagnostics.svelte` 的 `openEntry`), 所以顺序几乎
       * 总是: 请求已经躺在 store 里 → 文件读完 → 本 effect 建实例。放在这里就没有两个 effect 的
       * 先后与实例赋值时机问题: 实例一存在, 请求立刻兑现, 与恢复光标是同一步。
       */
      applyPendingReveal(instance, path, model);

      /*
       * 「拖一份相对路径进来」的落点。
       *
       * 从场景/资源浏览器或选项卡栏拖过来的, 是那一项「复制相对路径」的结果 (由源算好传过来),
       * 落点插入同样的文本 —— 两条入口共用 `lib/paths.ts` 的 `browserRelativePath`, 不在这里再算一遍。
       *
       * 落点位置必须自己求: 自定义拖拽没有 HTML5 的原生插入提示, 指针坐标要经
       * `getTargetAtClientPoint` 换算成缓冲区位置。点不到文字上 (行号槽 / 小地图 / 编辑器边缘)
       * 时退回当前光标, 而不是干脆不响应 —— 用户按下就落空比落错一行还费解。
       *
       * `forceMoveMarkers` 让光标与装饰跟着插入的文本走; 路径里没有换行, 因此结束后直接把列号
       * 加上长度就是插入内容的末端。
       */

      /** 拖动时那条"会插到这里"的竖线; 只在拖动期间显示, 由 `hover` 定位 */
      const dropCaret = document.createElement('div');
      dropCaret.className = 'drop-caret';
      dropCaret.hidden = true;
      container.appendChild(dropCaret);

      /**
       * 把竖线摆到指针所在的插入位置。
       *
       * 坐标取 `getScrolledVisiblePosition`: 它已经把行高、字符宽度、行号槽宽度与滚动都算进去了。
       * 自己按"字号 × 列号"算会在比例字体、折行与横向滚动上全错。
       */
      function placeDropCaret(point: { x: number; y: number } | null): void {
        const position = point ? instance.getTargetAtClientPoint(point.x, point.y)?.position : null;
        const visible = position ? instance.getScrolledVisiblePosition(position) : null;
        if (!visible) {
          dropCaret.hidden = true;
          return;
        }
        dropCaret.hidden = false;
        dropCaret.style.left = `${visible.left}px`;
        dropCaret.style.top = `${visible.top}px`;
        dropCaret.style.height = `${visible.height}px`;
      }

      const unregisterPathDrop = registerPathDropTarget(container, {
        insert: (text, point) => {
          if (readOnly) return false;
          const current = instance.getModel();
          if (!current) return false;
          const position = instance.getTargetAtClientPoint(point.x, point.y)?.position ?? instance.getPosition();
          if (!position) return false;
          instance.executeEdits('drop-relative-path', [
            { range: monaco.Range.fromPositions(position), text, forceMoveMarkers: true },
          ]);
          instance.pushUndoStop();
          const end = { lineNumber: position.lineNumber, column: position.column + text.length };
          instance.setPosition(end);
          instance.revealPositionInCenterIfOutsideViewport(end);
          instance.focus();
          return true;
        },
        /*
         * 拖动过程中的"插入位置"提示。
         *
         * 自定义拖拽没有原生 caret, 也不方便改鼠标指针 (源元素捕获了指针, 光标由它决定), 所以
         * 自己画一条竖线 —— 与文本插入符同位置、同行高。
         */
        hover: (point) => {
          if (readOnly) return false; // 插不进去就别给出"可以插"的提示
          placeDropCaret(point);
          return true;
        },
      });

      /*
       * 实时预览指示器 (行号旁那个图标)。
       *
       * `getMarker` 必须**按本文档过滤**: store 里的 `livePreviewMarker` 是全局单例, 直接返回
       * 会把 A 文档的标记画到 B 文档同一行上 (切卡瞬间尤其明显); 而控制器又会周期性重画, 所以
       * 这个错误标记不会自己消失, 而是一路跟到别的文件上。
       */
      const previewGutter = createLivePreviewGutterController({
        editor: instance,
        getMarker: () => {
          const marker = untrack(() => appStore.livePreviewMarker);
          return marker?.docPath === path ? marker : null;
        },
        isReplayAvailable: () => untrack(() => appStore.previewReady),
        onReplay: (line) => actions.requestPreviewReplay(line),
      });

      /*
       * 上一次真正画出去的色块签名。
       *
       * `applyGitGutter` 有**两个触发源** (git 状态变化 + 每次内容变化), 而 `git/status.ts`
       * 又会在项目里**任何**文件变化后 400ms 刷新一次状态 (编辑器自己的自动保存在 800ms 后就
       * 会写盘), 因此它会被高频调用, 而多数调用算出来的色块与上一次完全相同。`collection.set()`
       * 会拆掉旧装饰重插 DOM —— 内容没变时重画一遍, 视觉上就是行号旁的色块在闪。算完先比签名,
       * 一样就不动 DOM。
       */
      let lastGitKey: string | null = null;

      /*
       * 重算 git 色块。提成函数是因为它有**两个触发源**: git 状态变化, 以及**用户打字** ——
       * 只在状态变化时算的话, 用户改完一行不会看到色块跟着动, 得等下一次 git 状态刷新, 而那个
       * 刷新由文件监听驱动, 编辑器自己的改动不一定能触发它 (内容还没落盘)。
       */
      async function applyGitGutter(): Promise<void> {
        const status = untrack(() => appStore.gitStatus);
        const projectPath = untrack(() => appStore.projectPath);
        /*
         * 这里**不再判断 `readOnly`**。
         *
         * 配音卡就是只读的, 但它恰恰是最需要看见"这个文件改了什么"的地方 —— 「应用」一条配音
         * 本来就是在改这个文件。只读约束的是"你自己敲字", 不是"看变化": 多加一个 `readOnly`
         * 条件, 配音卡里整条色块都不画。
         *
         * `readOnly` 的其它用途 (禁止写入 / 隐藏插入符 / Ctrl+S 语义) 不受影响。
         */
        if (!status || !projectPath) return;

        const model = instance.getModel();
        if (!model) return;

        // 脏文档用内存内容算差异 —— 否则色块会跟屏幕上看到的内容对不上
        const dirty = untrack(() => appStore.documents.find((item) => item.path === path)?.dirty ?? false);
        const content = dirty ? model.getValue() : undefined;
        const relative = relativePathOf(projectPath, path);

        try {
          const changes = await gitFileChanges(projectPath, relative, content);
          // 等待期间文档可能已经切换/销毁, 因此拿到结果后再确认一次 model 还在
          if (instance.getModel() !== model) return;
          const marks = diffGutterMarks(changes, model.getLineCount(), (line) => model.getLineMaxColumn(line));
          const key = marks.map((mark) => `${mark.className}@${mark.lineNumber}:${mark.endColumn}`).join(',');
          if (key === lastGitKey) return;
          lastGitKey = key;
          collectionFor(gitCollections, instance).set(
            marks.map((mark) => ({
              range: new monaco.Range(mark.lineNumber, 1, mark.lineNumber, mark.endColumn),
              options: { isWholeLine: true, linesDecorationsClassName: mark.className },
            }))
          );
        } catch {
          // git 出错不该影响编辑
        }
      }

      /*
       * 行内差异区域: 点行号旁的 git 色块就地在下一行展开"改了什么"。
       *
       * 差异内容现拉现取 (`git_file_region`) 而不是跟着色块一起算: 色块每条改动都要画, 而展开
       * 是极低频的操作, 没必要为它把整份差异常驻在内存里。
       */
      const inlineDiff = createInlineDiffZoneController({
        editor: instance,
        loadRegion: async (line) => {
          const projectPath = untrack(() => appStore.projectPath);
          if (!projectPath) return null;
          const dirty = untrack(() => appStore.documents.find((item) => item.path === path)?.dirty ?? false);
          const current = instance.getModel()?.getValue();
          return gitFileRegion(projectPath, relativePathOf(projectPath, path), line, dirty ? current : undefined);
        },
      });

      /** 点 git 色块 -> 展开/收起行内差异。 */
      const gutterClickSub = instance.onMouseDown((event) => {
        const target = event.target;
        const decorations =
          target.type === monaco.editor.MouseTargetType.GUTTER_LINE_DECORATIONS ||
          target.type === monaco.editor.MouseTargetType.GUTTER_GLYPH_MARGIN;
        if (!decorations) {
          /*
           * 点编辑区内容 (非差异区) 关闭内联差异: 只在**有展开的区域**时才拦 —— 否则每一次普通
           * 点击都要走一遍 `closest()`, 而 `gutterMargin` 那一栏在场景文件里几乎占了行号旁的
           * 全部宽度。
           */
          if (inlineDiff.openLine() !== null) {
            const element = event.target.element as HTMLElement | null;
            if (!element?.closest('.inline-diff-zone')) inlineDiff.close();
          }
          return;
        }
        const line = target.position?.lineNumber;
        if (!line) return;
        void inlineDiff.toggle(line);
      });

      /** Esc 关闭内联差异 (与对话框一致的"退出当前浮层"手势)。 */
      const escapeSub = instance.onKeyDown((event) => {
        if (event.keyCode !== monaco.KeyCode.Escape) return;
        if (inlineDiff.openLine() === null) return;
        event.preventDefault();
        event.stopPropagation();
        inlineDiff.close();
      });

      const gitDecorations = collectionFor(gitCollections, instance);
      // 让"实例之外"的 git 状态变化也能触发这里重算 (见 `applyGutterFor`)
      gutterHooks.set(instance, () => void applyGitGutter());
      const highlightDecorations = collectionFor(highlightCollections, instance);

      /*
       * 悬浮文档 / 补全详情里的外链走**系统浏览器**。
       *
       * Monaco 自己会把 `<a href>` 当普通导航处理 —— 在 Tauri 里那等于让整个 WebView 跳走,
       * 编辑器连同未保存的内容一起消失。因此在 document 的**捕获阶段**拦下来, 只认
       * `https?:` 与 `mailto:`, 并限定在编辑器的 DOM 子树内 (别影响应用里别处的链接)。
       */
      const onHoverLinkClick = (event: MouseEvent) => {
        const target = event.target as HTMLElement | null;
        if (!target || typeof target.closest !== 'function') return;
        const anchor = target.closest('a');
        if (!anchor) return;
        if (!anchor.closest('.monaco-hover') && !anchor.closest('.suggest-details')) return;
        const root = instance.getDomNode();
        if (!root || !root.contains(anchor)) return;
        const href = anchor.dataset['href'] || anchor.getAttribute('href') || '';
        if (!/^(https?:|mailto:)/i.test(href)) return;
        event.preventDefault();
        event.stopPropagation();
        void openUrl(href);
      };
      document.addEventListener('click', onHoverLinkClick, true);

      const docSaver = createDocumentSaver({
        read: () => instance.getValue(),
        write: (text) => fs.writeText(path, text),
        commit: (text) => actions.updateDocument(path, { content: text, dirty: false }),
        onError: (error) => console.error('保存失败', error),
      });

      // 定时器先声明再用: 内容回调是同步触发的, 声明晚了会落进暂时性死区。
      let saveTimer: ReturnType<typeof setTimeout> | null = null;
      let syncTimer: ReturnType<typeof setTimeout> | null = null;

      function scheduleSave(): void {
        if (!untrack(() => appStore.settings.autoSave)) return;
        if (saveTimer) clearTimeout(saveTimer);
        saveTimer = setTimeout(() => void docSaver.save(), AUTOSAVE_DELAY);
      }

      /**
       * 防抖同步预览: 有未保存改动且开了自动保存时先落盘再同步 —— 预览读的是磁盘上的文件,
       * 不先保存的话引擎执行到的还是上一版内容。
       */
      function scheduleSync(): void {
        if (!untrack(() => appStore.settings.autoSyncPreview)) return;
        if (syncTimer) clearTimeout(syncTimer);
        syncTimer = setTimeout(() => {
          const position = instance.getPosition();
          if (!position) return;
          const dirty = untrack(() => appStore.documents.find((item) => item.path === path)?.dirty ?? false);
          const push = () => void previewClient.syncScene(path, position.lineNumber);
          if (dirty && untrack(() => appStore.settings.autoSave)) void docSaver.save().then(push);
          else push();
        }, PREVIEW_SYNC_DELAY);
      }

      function onContentChanged(text: string): void {
        if (pushingExternal) return;
        actions.updateDocument(path, { content: text, dirty: true });
        // 内容变了, 已展开的行内差异挂在旧行号上, 先收起再重算色块
        inlineDiff.close();
        void applyGitGutter();
        scheduleSave();
        scheduleSync();
      }

      // 让"外部内容回灌"那个 effect 也能触发一次预览同步 (见 `syncRef` 的说明)
      syncRef = () => scheduleSync();

      /*
       * 内容 -> store / 语言服务。
       *
       * 场景文档走 `bindModel` (它负责 didChange, 并在 model 销毁时 didClose); 普通文本文件
       * 不参与语言服务, 但要写回 store 才能让状态栏的字符/行数与"脏"标记正确。
       */
      const unbind = isScene
        ? bindModel(model, path, onContentChanged)
        : (() => {
            const sub = model.onDidChangeContent(() => onContentChanged(model.getValue()));
            return () => sub.dispose();
          })();

      /**
       * 光标 -> store (状态栏显示 / 配音卡定位 / 切卡恢复)。
       *
       * 另外: **光标跨行时触发一次预览同步** —— 这是"移动光标预览就跟着跳"的实现; 只在同一行内
       * 左右移动不该发 (否则每按一次方向键都要跑一遍"必要先落盘 + 发同步"), `lastSyncLine` 用来去重。
       */
      let lastSyncLine = 0;
      const cursorSub = instance.onDidChangeCursorPosition((event) => {
        const line = event.position.lineNumber;
        actions.setCursor({ path, line, column: event.position.column });
        actions.rememberCursor(path, { line, column: event.position.column });
        if (line === lastSyncLine) return;
        lastSyncLine = line;
        scheduleSync();
      });

      /** Ctrl+S 立即落盘 */
      instance.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyS, () => {
        void docSaver.save();
      });

      /** 只读模式 (配音卡) 也要能撤回「应用」, 因此单独给撤销/重做 */
      if (readOnly) {
        instance.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyZ, () => {
          instance.trigger('keyboard', 'undo', null);
        });
        instance.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyMod.Shift | monaco.KeyCode.KeyZ, () => {
          instance.trigger('keyboard', 'redo', null);
        });
      }

      /*
       * 补全后的自动重新触发: 语言服务补齐 `key:value;` 这类片段后, 用户接着要写下一个参数, 而
       * Monaco 不会自己再弹一次 —— 这里在刚输入触发字符时补一次。
       */
      const suggestSub = model.onDidChangeContent(() => {
        if (pushingExternal) return;
        const position = instance.getPosition();
        if (!position) return;
        const line = model.getLineContent(position.lineNumber).slice(0, position.column - 1);
        if (!TRIGGER_SET.has(line.at(-1) ?? '')) return;
        instance.trigger('keyboard', 'editor.action.triggerSuggest', null);
      });

      /*
       * 下面几个观察者替代了 `useAppStore.subscribe((state, prev) => ...)`: 它们只在关心的字段
       * 真的变化时动手, 因此**不会**引起编辑器重建。
       *
       * ⚠️ `select()` 里**不能**再用 `untrack()` 包住取值: 观察者本身就是 `$effect` (见
       * `state/watch.svelte.ts`), 包了 `untrack` 等于切断依赖, 这个观察者再也不会被唤醒
       * (改了设置没反应, 且不报错)。
       */
      const settingsWatcher = watchValues({
        select: () => [appStore.settings.editorFontFamily],
        onChange: () => instance.updateOptions({ fontFamily: appStore.settings.editorFontFamily }),
      });
      const fontSizeWatcher = watchValues({
        select: () => [appStore.settings.editorFontSize],
        onChange: () => instance.updateOptions({ fontSize: appStore.settings.editorFontSize }),
      });
      const wrapWatcher = watchValues({
        select: () => [appStore.settings.editorWordWrap],
        onChange: () => instance.updateOptions({ wordWrap: appStore.settings.editorWordWrap ? 'on' : 'off' }),
      });
      const minimapWatcher = watchValues({
        select: () => [appStore.settings.editorMinimap],
        onChange: () => instance.updateOptions({ minimap: { enabled: appStore.settings.editorMinimap } }),
      });
      const themeWatcher = watchValues({
        select: () => [appStore.theme],
        onChange: () => monaco.editor.setTheme(appStore.theme === 'dark' ? 'webgal-dark' : 'webgal-light'),
      });
      const diagnosticsWatcher = watchValues({
        // 只看本文档那一份诊断: 全项目重推时其余文件的条目被替换, 这里的值不变 → 不唤醒。
        select: () => [appStore.diagnostics[path]],
        onChange: () => applyDiagnostics(model, path),
      });
      const previewWatcher = watchValues({
        /*
         * 实时预览指示器 + 预览就绪状态。
         *
         * `livePreviewMarker` 在 store 里已改成"内容不变就不替换"(见 `store.svelte.ts` 的
         * `beginLivePreview`), 因此这里只在**真正的新标记**上被唤醒 —— 不再是"每次 syncScene
         * 都重画一遍装饰"。
         */
        select: () => [appStore.livePreviewMarker, appStore.previewReady],
        onChange: () => previewGutter.sync(),
      });

      /** 预览就绪的**上升沿**: 把当前光标行补发一次 (重挂或重连后引擎还没收到位置)。 */
      let wasReady = appStore.previewReady;
      const readyWatcher = watchValues({
        select: () => [appStore.previewReady],
        onChange: () => {
          const ready = appStore.previewReady;
          const rising = ready && !wasReady;
          wasReady = ready;
          if (!rising) return;
          if (!appStore.settings.autoSyncPreview) return;
          const position = instance.getPosition();
          if (position) void previewClient.syncScene(path, position.lineNumber);
        },
      });

      // 初始状态: 诊断与指示器都按当前值画一次
      applyDiagnostics(model, path);
      previewGutter.sync();

      return () => {
        if (saveTimer) clearTimeout(saveTimer);
        if (syncTimer) clearTimeout(syncTimer);
        settingsWatcher.stop();
        fontSizeWatcher.stop();
        wrapWatcher.stop();
        minimapWatcher.stop();
        themeWatcher.stop();
        diagnosticsWatcher.stop();
        previewWatcher.stop();
        readyWatcher.stop();
        suggestSub.dispose();
        cursorSub.dispose();
        escapeSub.dispose();
        document.removeEventListener('click', onHoverLinkClick, true);
        syncRef = null;
        unregisterPathDrop();
        dropCaret.remove();
        unbind();
        gutterClickSub.dispose();
        inlineDiff.dispose();
        previewGutter.dispose();
        gitDecorations.clear();
        highlightDecorations.clear();
        instance.dispose();
        editor = null;
      };
    });
  });

  // ---------------------------------------------------------------------------
  // 2. 更新实例 —— 只推值, 不重建
  // ---------------------------------------------------------------------------

  /**
   * 外部内容回灌。
   *
   * 必须用 `applyEdits` **而不是 `setValue`**: 后者清空撤销栈, 配音卡里"应用"一次就再也
   * 撤不回去。`pushingExternal` 保证这次变更不会被当成用户编辑而标脏。
   */
  $effect(() => {
    const content = doc.content;
    void doc.path;
    const instance = untrack(() => editor);
    if (!instance) return;
    const model = instance.getModel();
    if (!model || model.isDisposed() || model.getValue() === content) return;

    /*
     * `pushingExternal` **必须**用 `try/finally` 复位, 而且只有这一处能写它。
     *
     * 它是"这次内容变化不是用户敲的"的唯一判据 (`onContentChanged` 靠它提前返回)。一旦卡在
     * `true`, 这个编辑器的**整条编辑链路**就静默死掉, 症状是三条一起发生: 打字不再写回 store
     * (没有脏标记 → 自动保存不再发生, 标签上的脏点也不亮)、`applyGitGutter()` 只在内容回调里
     * 触发 (行号旁的差异色块不再更新)、状态栏的字符数与行号也不再跟着动 —— 看上去像"编辑器
     * 卡住不能用了"。裸赋值时 `applyEdits` 或 `setPosition` 只要抛一次 (模型被销毁、实例已
     * dispose) 标志就永远是 `true`, 因此这里必须 `try/finally`, 并补一道 `isDisposed()` 前置
     * 判据、把失败记进控制台。
     */
    pushingExternal = true;
    try {
      const position = instance.getPosition();
      /*
       * **选区要保住** —— 不只是光标。
       *
       * 点诊断跳转是"先写请求、再读文件" (见 `Diagnostics.svelte` 的 `openEntry`), 因此顺序
       * 常常是: 编辑器先按请求**选中**了诊断那一段, 紧接着内容回灌 (`applyEdits` 整体替换)
       * 把选区清掉。只恢复 `position` 的话, 用户看到的就是"先选中, 然后很快消失"; 有非空选区
       * 时优先恢复选区 (Monaco 会自行夹取范围), 否则退回恢复光标。
       *
       * ⚠️ **先把选区摘成基本类型**: `getSelection()` 拿到的实例是光标状态里的**活对象**, 而
       * `applyEdits` 会让视图模型重新推导光标状态 (内部对 `Selection` 有就地改写的方法), 留到
       * 之后再用可能已经不是当初那一段 (空选区或被夹到别处)。摘成四个行/列数字之后, 是否恢复
       * 与 Monaco 内部如何更新无关。
       */
      const selection = instance.getSelection();
      const restoreSelection =
        selection && !selection.isEmpty()
          ? {
              startLineNumber: selection.startLineNumber,
              startColumn: selection.startColumn,
              endLineNumber: selection.endLineNumber,
              endColumn: selection.endColumn,
            }
          : null;
      model.applyEdits([{ range: model.getFullModelRange(), text: content }]);
      if (restoreSelection) {
        instance.setSelection(
          new monaco.Range(
            restoreSelection.startLineNumber,
            restoreSelection.startColumn,
            restoreSelection.endLineNumber,
            restoreSelection.endColumn
          )
        );
      } else if (position) {
        instance.setPosition(position);
      }
    } catch (error) {
      console.error('外部内容回灌失败', doc.path, error);
    } finally {
      pushingExternal = false;
    }

    /*
     * 回灌之后要补两件事, 否则"外部改了内容"这个事实传不出去: **非场景文档**没有绑定 model,
     * 语言服务不知道内容变了 (补一次 `changeDocument`, 否则诊断与语义高亮一直基于旧内容);
     * **预览**需要跟着跳一次 (回灌通常是"配音应用"或"加载磁盘", 光标行往往已经变了)。
     */
    if (!doc.isScene) lspClient.changeDocument(doc.path, content, model.getVersionId());
    syncRef?.();
  });

  /**
   * 兑现一次待处理的跳转请求 (**含整段选中**), 返回是否真的消费了它。
   *
   * 两个调用点: ① 实例刚建好时 (请求通常先于实例到达, 见建实例 effect 里的说明);
   * ② 文件已经打开、用户在诊断列表里又点了一条 (`$effect` 观察 `revealRequest`)。
   *
   * 三种情形: 有非空范围 → 选中它 (点诊断想看的正是"被标红的是哪几个字"); 有 end 但范围为空
   * (诊断指向两个字符之间, 例如"这里少了个分号") → 选中**整行**; 没有 end → 只放光标。
   */
  function applyPendingReveal(
    instance: monaco.editor.IStandaloneCodeEditor,
    path: string,
    model: monaco.editor.ITextModel
  ): boolean {
    const request = untrack(() => appStore.revealRequest);
    if (!request || request.path !== path) return false;

    const line = Math.min(Math.max(1, request.line), model.getLineCount());
    const column = Math.min(Math.max(1, request.column), model.getLineMaxColumn(line));
    const endLine = Math.min(Math.max(line, request.endLine ?? line), model.getLineCount());
    const endColumn = Math.min(Math.max(1, request.endColumn ?? column), model.getLineMaxColumn(endLine));

    if (endLine > line || endColumn > column) {
      instance.setSelection(new monaco.Range(line, column, endLine, endColumn));
    } else if (request.endLine !== undefined) {
      instance.setSelection(new monaco.Range(line, 1, line, model.getLineMaxColumn(line)));
    } else {
      instance.setPosition({ lineNumber: line, column });
    }
    instance.revealLineInCenterIfOutsideViewport(line);
    instance.focus();
    // 请求是"一次性动作"而不是"当前状态": 消费完立刻清掉, 否则切回来会又跳一次
    actions.clearReveal();
    return true;
  }

  /** 文件已经打开时, 诊断列表再点一条走这里 (`editor` 读成依赖: 实例晚于请求就绪也要补做)。 */
  $effect(() => {
    const request = appStore.revealRequest;
    const path = doc.path;
    const instance = editor;
    if (!request || !instance || request.path !== path) return;
    const model = instance.getModel();
    if (!model) return;
    applyPendingReveal(instance, path, model);
  });

  /** 重跑某一行 (预览指示器点击)。 */
  $effect(() => {
    const replay = appStore.previewReplay;
    const path = doc.path;
    if (!replay) return;
    /*
     * 令牌式请求: **先消费再执行** (与诊断跳转的 `clearReveal` 同构)。
     *
     * 不消费的话, 这个 effect 的其它依赖 (`previewReady` / `autoSyncPreview`) 一变就会把同一
     * 条旧请求再发一遍 —— 预览重连的那一刻会莫名其妙又跑一次上次点的那行。指示器本身只在
     * `previewReady` 时可点 (`isReplayAvailable`), 因此不必为"没连上"保留请求。
     */
    actions.clearPreviewReplay();
    if (!appStore.settings.autoSyncPreview || !appStore.previewReady) return;
    void previewClient.syncScene(path, replay.line, true);
  });

  /**
   * 上一次整行高亮的签名。
   *
   * 配音卡的父组件每次都传一个**字面量对象** `{ line, count }`, 因此这个 effect 会因为"引用
   * 变了"而反复触发, 而它每次都会 `collection.set()` (拆装饰 + 重插 DOM) —— 高亮内容没变时
   * 重画一遍, 视觉上就是那条整行底色在闪。这里按内容去重。
   *
   * 签名里带 `model.uri`: 换卡时模型被替换, Monaco 会清掉装饰, 那时必须重画。
   */
  let lastHighlightKey: string | null = null;

  /** 整行高亮: 配音卡用它指出"当前语句"。传 null 时要清掉上一次的高亮。 */
  $effect(() => {
    const target = highlightLine;
    const instance = untrack(() => editor);
    if (!instance) return;
    const model = instance.getModel();
    if (!model) return;
    const key = `${model.uri.toString()}|${target ? `${target.line}:${target.count}` : ''}`;
    if (key === lastHighlightKey) return;
    lastHighlightKey = key;

    const collection = collectionFor(highlightCollections, instance);
    if (!target) {
      collection.clear();
      return;
    }
    // 后端给的是 **0 基** 行号, Monaco 是 1 基
    const line = Math.min(target.line + 1, model.getLineCount());
    const endLine = Math.min(line + Math.max(1, target.count) - 1, model.getLineCount());
    collection.set([
      {
        range: new monaco.Range(line, 1, endLine, model.getLineMaxColumn(endLine)),
        options: { isWholeLine: true, className: 'voice-line-highlight' },
      },
    ]);
  });

  /** git 色块随 git 状态刷新 (打字时的重算在实例内部的内容回调里触发)。 */
  $effect(() => {
    const status = appStore.gitStatus;
    void status;
    const instance = untrack(() => editor);
    if (!instance) return;
    applyGutterFor(instance);
  });

  /**
   * 让"当前实例"重算色块。
   *
   * 色块的计算逻辑在**建实例**的 effect 里 (它需要 model、docSaver 等实例内的东西), 而触发源在
   * 实例之外 (`appStore.gitStatus`) —— 用一个按实例登记的钩子接起来, 比把整段逻辑复制到外面稳
   * (复制出来的那份迟早会跟里面那份走偏)。
   */
  const gutterHooks = new WeakMap<monaco.editor.IStandaloneCodeEditor, () => void>();

  function applyGutterFor(instance: monaco.editor.IStandaloneCodeEditor): void {
    gutterHooks.get(instance)?.();
  }
</script>

<div class="code-editor-host" class:drop-target={pathDrag.target === host} bind:this={host}></div>
